// behaviour: owns the state and the transitions
type Disclosure struct{ expanded bool }
func (d *Disclosure) Toggle()        { d.expanded = !d.expanded }
func (d *Disclosure) Expanded() bool { return d.expanded }
func (d *Disclosure) AriaExpanded() string {
    if d.expanded { return "true" }
    return "false"
}

// markup: the consumer supplies the template
// {{define "disclosure"}}<button aria-expanded="{{.AriaExpanded}}">...</button>{{end}}
tmpl.ExecuteTemplate(w, "disclosure", d)
